/* cppi::e5260f05c7d6aee480adea51a6418edfcfbf6adbdaff5511174f185dae723629 */
select enterprise_security_id, cppib_sec_id,abor_security_number, * from asset.enterprise_security 
 where business_date = date '2025-05-23' and  enterprise_security_id in ('24607067-cppibID','26533492-cppibID','1634-cppibID','29016093-cppibID','11616545-cppibID','592519-cppibID','223032-cppibID','512424-cppibID','164311-cppibID','19304655-cppibID' )

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

